{
  "query": "select:WebSearch,WebFetch",
  "max_results": 2
}

{
  "query": "Riley 2015 Space Weather \"inner heliosphere models\" WSA velocity 285 625 (1+fs)^(2/9) exp(-(d/w)^beta)",
  "mode": "standard"
}

{
  "query": "Pomoell Poedts 2018 EUHFORIA inner boundary velocity 240 675 (1+f)^0.222 0.8 exp w β",
  "mode": "standard"
}

{
  "url": "https://www.swsc-journal.org/articles/swsc/full_html/2018/01/swsc180020/swsc180020.html",
  "prompt": "Extract verbatim the inner boundary conditions of the solar wind: the velocity formula (eq numbers), values of v0, v1, alpha, w, beta, any 50 km/s reduction, any maximum cap (675?), the density formula n = n_fsw (v_fsw/v)^2 with values, temperature formula and values T_fsw, magnetic field Br prescription (B_fsw, sign, scaling), the plasma pressure, and the inner boundary radius. Also the DOI and article number."
}

{
  "query": "Pomoell Poedts 2018 \"EUHFORIA: European heliospheric forecasting information asset\" arxiv",
  "mode": "standard"
}

{
  "url": "https://www.swsc-journal.org/articles/swsc/full_html/2018/01/swsc170062/swsc170062.html",
  "prompt": "Extract verbatim the inner boundary conditions of the heliospheric model: the velocity formula (equation numbers), values of v0, v1, alpha, w, beta; any 50 km/s reduction; any maximum cap; the density formula with n_fsw, v_fsw values; temperature formula and T_fsw; magnetic field Br prescription (B_fsw, sign, scaling); inner boundary radius. Also cone CME defaults if mentioned."
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/1907.07461",
  "prompt": "Extract verbatim the EUHFORIA inner boundary conditions: WSA velocity formula with constants (v0, v1, alpha, w, beta), the 50 km/s subtraction, the clamp/cap values, density formula n = n_fsw (v_fsw/v)^2 and n_fsw, v_fsw values, temperature T_fsw and its rule, the magnetic field Br rule (B_fsw value, sign from PFSS), plus which equations are attributed to Pomoell & Poedts 2018. Also the paper's authors, journal, year."
}

{
  "url": "https://arxiv.org/html/2405.09693",
  "prompt": "Extract verbatim: the EUHFORIA default WSA formula and constants (V0, V1, alpha, w, beta), any 50 km/s subtraction, min/max speed caps, density, temperature/pressure and B rules at 0.1 au, and the new PSP-calibrated constants proposed in this paper. Also authors, journal, year, DOI."
}

{
  "query": "Arge 2003 AIP Conference Proceedings 679 190 \"improved method for specifying solar wind speed\" formula 265 expansion factor θb",
  "mode": "standard"
}

{
  "query": "McGregor 2011 JGR A03101 WSA solar wind speed 240 675 (1+fs)^(1/4.5) w beta 1.25",
  "mode": "standard"
}

{
  "url": "https://research.ssl.berkeley.edu/cism/papers/Arge03.pdf",
  "prompt": "Give verbatim the empirical solar wind speed equation(s) relating speed to expansion factor fs and theta_b (angular distance to coronal hole boundary), including all numerical coefficients, units, and the radius at which it applies. Also any statement about the speed being assigned at 21.5 Rs/0.1 AU or at 5 Rs."
}

{
  "file_path": "/home/scabot/.claude/projects/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/tool-results/webfetch-1792191650228-ofdli0.pdf",
  "pages": "1-4"
}

{
  "query": "Arge et al. 2003 solar wind speed \"265\" \"(1+f_s)^{1/3}\" \"5.8\" \"1.6\" \"7.5\" θb",
  "mode": "standard"
}

{
  "query": "Arge 2004 JASTP 66 1295 \"Stream structure and coronal sources of the solar wind during the May 12th, 1997 CME\" velocity formula expansion factor coefficients",
  "mode": "standard"
}
